class JobReference {
  /// The job ID, which must be unique within the project. The job ID is generated by the server upon job submission or provided by the user as a means to perform retries without creating duplicate jobs
  final String? jobId;

  /// Creates a new [JobReference].
  /// [jobId] The job ID, which must be unique within the project. The job ID is generated by the server upon job submission or provided by the user as a means to perform retries without creating duplicate jobs
  JobReference({
    this.jobId,
  });

  Map<String, dynamic> toMap() {
    return <String, dynamic>{
      'jobId': ?jobId,
    };
  }

  factory JobReference.fromMap(Map<String, dynamic> map) {
    return JobReference(
      jobId: map['jobId'] == null ? null : map['jobId'] as String,
    );
  }
}

